"""
Bondville/Champaign, IL TMY3 weather data for the IRCC data-center chiller,
EMBEDDED directly in this file -- no external .txt/.csv to load, no file
path to break when this module gets copied/imported elsewhere.

Source: NREL TMY3, WMO#725315 (Univ of Illinois Willard Airport, Bondville IL)
Fields per hour: month, day, hour, T_db[C], T_dp[C], RH[%], P[Pa],
                 wind_dir[deg], wind_speed[m/s], sky_cover[tenths],
                 opaque_sky_cover[tenths]
"""

import numpy as np
from dataclasses import dataclass


@dataclass
class HourlyWeather:
    """One hour of TMY weather data."""
    hour_of_year: int   # 0-8759, index into ChampaignWeather arrays
    month: int
    day: int
    hour: int            # 1-24 (EPW convention: "1" = 00:00-01:00 ... "24" = 23:00-24:00)
    T_db: float           # dry-bulb temperature [C]
    T_dp: float           # dew-point temperature [C]
    RH: float              # relative humidity [%]
    P: float                # station pressure [Pa]
    wind_dir: float          # wind direction [deg from north]
    wind_speed: float        # wind speed [m/s]
    sky_cover: float          # total sky cover [tenths]
    opaque_sky_cover: float    # opaque sky cover [tenths]

    @property
    def T_db_K(self):
        return self.T_db + 273.15


LOCATION = dict(
    city="Univ Of Illinois Wi  Bondville", state="IL", country="USA",
    source="TMY3", wmo="725315", latitude=40.06, longitude=-88.37,
    tz_offset=-6.0, elevation_m=213.0,
)

