class ChampaignWeather:
    """
    Full-year (8760 h) TMY3 weather data for Bondville/Champaign, IL, parsed
    from the embedded _RAW_DATA string above -- into numpy arrays for fast
    vectorized use plus an indexable/iterable list of HourlyWeather records.

    USAGE
    -----
        from weather import ChampaignWeather

        wx = ChampaignWeather()          # no file path needed -- data is embedded

        wx.T_db                 -> np.array, shape (8760,), outdoor dry-bulb [C]
        wx[0]                    -> HourlyWeather for hour 0 of the year (Jan 1, hr 1)
        wx.get_hour(7, 15, 14)    -> HourlyWeather for July 15, 2 PM

        for hr in wx:
            if hr.T_db <= 4.0:
                ...   # economizer / free-cooling mode this hour
            else:
                ...   # compressor mode this hour
    """

    N_HOURS = 8760

    def __init__(self):
        self.location = LOCATION
        self.hourly = []
        self._parse()
        self._build_arrays()

    def _parse(self):
        lines = [ln for ln in _RAW_DATA.strip().splitlines() if ln.strip()]
        if len(lines) != self.N_HOURS:
            raise ValueError(
                f"expected {self.N_HOURS} embedded hourly rows, found {len(lines)}"
            )
        for i, line in enumerate(lines):
            p = line.split(",")
            self.hourly.append(HourlyWeather(
                hour_of_year=i,
                month=int(p[0]), day=int(p[1]), hour=int(p[2]),
                T_db=float(p[3]), T_dp=float(p[4]), RH=float(p[5]),
                P=float(p[6]), wind_dir=float(p[7]), wind_speed=float(p[8]),
                sky_cover=float(p[9]), opaque_sky_cover=float(p[10]),
            ))

    def _build_arrays(self):
        self.month = np.array([h.month for h in self.hourly])
        self.day = np.array([h.day for h in self.hourly])
        self.hour = np.array([h.hour for h in self.hourly])
        self.T_db = np.array([h.T_db for h in self.hourly])
        self.T_dp = np.array([h.T_dp for h in self.hourly])
        self.RH = np.array([h.RH for h in self.hourly])
        self.P = np.array([h.P for h in self.hourly])
        self.wind_speed = np.array([h.wind_speed for h in self.hourly])
        self.wind_dir = np.array([h.wind_dir for h in self.hourly])
        self.sky_cover = np.array([h.sky_cover for h in self.hourly])

    def __len__(self):
        return self.N_HOURS

    def __getitem__(self, hour_of_year):
        return self.hourly[hour_of_year]

    def __iter__(self):
        return iter(self.hourly)

    def get_hour(self, month, day, hour):
        for h in self.hourly:
            if h.month == month and h.day == day and h.hour == hour:
                return h
        raise ValueError(f"no record for {month}/{day} hour {hour}")

    def economizer_hours(self, threshold_C=4.0):
        return self.T_db <= threshold_C

    def summary(self):
        return {
            "T_db_min_C": float(self.T_db.min()),
            "T_db_max_C": float(self.T_db.max()),
            "T_db_mean_C": float(self.T_db.mean()),
            "T_db_0.4%_C": float(np.percentile(self.T_db, 99.6)),
            "T_db_99.6%_C": float(np.percentile(self.T_db, 0.4)),
            "RH_mean_%": float(self.RH.mean()),
            "wind_speed_mean_ms": float(self.wind_speed.mean()),
            "economizer_hours": int(self.economizer_hours().sum()),
            "economizer_pct_of_year": float(100 * self.economizer_hours().mean()),
        }

    def print_summary(self):
        s = self.summary()
        print(f"=== {self.location['city']}, {self.location['state']} "
              f"(WMO {self.location['wmo']}) -- {self.N_HOURS}-hour TMY3 ===")
        print(f"Dry bulb   : min {s['T_db_min_C']:.1f} C | mean {s['T_db_mean_C']:.1f} C "
              f"| max {s['T_db_max_C']:.1f} C")
        print(f"Design pts : {s['T_db_0.4%_C']:.1f} C (0.4% cooling)  /  "
              f"{s['T_db_99.6%_C']:.1f} C (99.6% heating)")
        print(f"RH mean    : {s['RH_mean_%']:.0f} %   Wind mean: {s['wind_speed_mean_ms']:.1f} m/s")
        print(f"Free cooling (T_db <= 4 C): {s['economizer_hours']} h/yr "
              f"({s['economizer_pct_of_year']:.1f}% of the year)")


if __name__ == "__main__":
    wx = ChampaignWeather()
    wx.print_summary()
